#include <vector>
#include <algorithm>
#include <string>
using namespace std;

struct Student { string name; int mark; };

int main() {
    vector<Student> cls = {{"Amina", 78}, {"Brian", 92}, {"Chebet", 60}};
    sort(cls.begin(), cls.end(), [](const Student &a, const Student &b) { return a.mark > b.mark; });
