## Inheritance and virtual functions

```cpp
class Shape {
public:
    virtual double area() const = 0;   // pure virtual: every shape must define it
    virtual ~Shape() = default;
};

class Rectangle : public Shape {
    double w, h;
public:
    Rectangle(double w, double h) : w(w), h(h) {}
